package ui.menu;import bll.services.TituloService;import javax.swing.*;import java.awt.*;public class DefinirCondicionesDialog extends JDialog {    private JPanel rootPanel;    private JLabel lblTitulo;    private JLabel tirada;    private JButton guardarButton;    private JButton cancelarButton;    private JTextField fldPrecio;    private JTextField fldPorcentaje;    private JTextField fldObservaciones;    private JTextField fldAutor;    private JTextField fldTirada;    private JTextField fldTitulo;    private final int propuestaId;    private final TituloService tituloService;    private boolean guardado;    private JTextField txtAutor;    private JTextField txtTitulo;    private JTextField txtTirada;    private JTextField txtPorcentaje;    private JTextField txtPrecio;    private JTextArea txtObservaciones;    public DefinirCondicionesDialog(Frame owner,                                    int propuestaId,                                    String autor,                                    String titulo,                                    TituloService tituloService) {        super(owner, "Definir Condiciones", true);        this.propuestaId = propuestaId;        this.tituloService = tituloService;        setContentPane(buildContent(autor, titulo));        pack();        setLocationRelativeTo(owner);        buildButtons();        getRootPane().setDefaultButton(guardarButton);    }    private JPanel buildContent(String autor, String titulo) {        JPanel panel = new JPanel(new BorderLayout(0, 10));        panel.setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));        JPanel form = new JPanel(new GridBagLayout());        GridBagConstraints gbc = new GridBagConstraints();        gbc.insets = new Insets(5, 5, 5, 5);        gbc.fill = GridBagConstraints.HORIZONTAL;        gbc.anchor = GridBagConstraints.WEST;        int row = 0;        gbc.gridx = 0;        gbc.gridy = row;        form.add(new JLabel("Autor:"), gbc);        txtAutor = new JTextField(autor);        txtAutor.setEditable(false);        gbc.gridx = 1;        form.add(txtAutor, gbc);        row++;        gbc.gridx = 0;        gbc.gridy = row;        form.add(new JLabel("Titulo:"), gbc);        txtTitulo = new JTextField(titulo);        txtTitulo.setEditable(false);        gbc.gridx = 1;        form.add(txtTitulo, gbc);        row++;        gbc.gridx = 0;        gbc.gridy = row;        form.add(new JLabel("Tirada inicial:"), gbc);        txtTirada = new JTextField();        gbc.gridx = 1;        form.add(txtTirada, gbc);        row++;        gbc.gridx = 0;        gbc.gridy = row;        form.add(new JLabel("Porcentaje autor (0-100):"), gbc);        txtPorcentaje = new JTextField();        gbc.gridx = 1;        form.add(txtPorcentaje, gbc);        row++;        gbc.gridx = 0;        gbc.gridy = row;        form.add(new JLabel("Precio por ejemplar:"), gbc);        txtPrecio = new JTextField();        gbc.gridx = 1;        form.add(txtPrecio, gbc);        row++;        gbc.gridx = 0;        gbc.gridy = row;        gbc.anchor = GridBagConstraints.NORTHWEST;        form.add(new JLabel("Observaciones:"), gbc);        txtObservaciones = new JTextArea(4, 20);        txtObservaciones.setLineWrap(true);        txtObservaciones.setWrapStyleWord(true);        gbc.gridx = 1;        form.add(new JScrollPane(txtObservaciones), gbc);        panel.add(form, BorderLayout.CENTER);        panel.add(buildButtons(), BorderLayout.SOUTH);        return panel;    }    private JPanel buildButtons() {        guardarButton = new JButton("Guardar");        cancelarButton = new JButton("Cancelar");        guardarButton.addActionListener(e -> guardar());        cancelarButton.addActionListener(e -> dispose());        JPanel buttons = new JPanel(new FlowLayout(FlowLayout.RIGHT));        buttons.add(cancelarButton);        buttons.add(guardarButton);        return buttons;    }    private void guardar() {        String resultado = tituloService.definirCondiciones(                String.valueOf(propuestaId),                txtTirada.getText(),                txtPorcentaje.getText(),                txtPrecio.getText(),                txtObservaciones.getText()        );        JOptionPane.showMessageDialog(                this,                resultado,                "Definir Condiciones",                JOptionPane.INFORMATION_MESSAGE        );        if (resultado != null && resultado.toLowerCase().contains("definidas")) {            guardado = true;            dispose();        }    }    public boolean isGuardado() {        return guardado;    }}